import { createContext } from "react";
import { jsx, jsxs } from "react/jsx-runtime";

const LAYERS = 24;
const contexts = Array.from({ length: LAYERS }, (_, index) => createContext(index));

const Layer = ({ index, children }) =>
  jsx(contexts[index].Provider, { value: index, children });

const Telemetry = () => null;

const Script = () => jsx("script", { type: "text/plain" });

export const AuthShell = ({ children }) =>
  contexts.reduceRight(
    (inner, _context, index) => jsx(Layer, { index, children: inner }),
    jsxs("div", { className: "auth-shell", children: [jsx(Telemetry, {}), jsx(Script, {}), children] }),
  );
